// commitHourlyFrom builds the per (date, hour, series) commit counts. The series
// label is the lowest canonical agent id among the checkpoints trailered onto the
// commit — "unknown" when they all resolve to it, and "none" when no checkpoint
// links the commit at all (its own series, not an absence). Sorted by date, then
// hour, then series, as the row fold sorted it.
func commitHourlyFrom(buckets []store.ActivityCommitBucket) []meHourlyContribution {
	type key struct {
		date   string
		hour   int
		series string
	}
	vals := map[key]int{}
	order := make([]key, 0, len(buckets))
	agents := make([]string, 0, 4) // scratch, reused: commitSeries only reads it
	for _, b := range buckets {
		// Canonicalise before labelling: two raw spellings of one agent are one
		// series, and the label is picked from canonical ids (commitSeries).
		agents = agents[:0]
		for _, raw := range b.Agents {
			agents = append(agents, getAgentID(raw))
		}
		k := key{b.Day, b.Hour, commitSeries(agents)}
		if _, ok := vals[k]; !ok {
			order = append(order, k)
		}
		vals[k] += b.Commits
	}
	out := make([]meHourlyContribution, 0, len(order))
	for _, k := range order {
		out = append(out, meHourlyContribution{Date: k.date, Hour: k.hour, Agent: k.series, Value: vals[k]})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Date != out[j].Date {
			return out[i].Date < out[j].Date
		}
		if out[i].Hour != out[j].Hour {
			return out[i].Hour < out[j].Hour
		}
		return out[i].Agent < out[j].Agent
	})
	return out
}

package store

import "strings"

// CommitState is a commit's lifecycle state, shared by the repo store
// (checkpoint_commits.commit_state), the user store (my_activity.state), the
// ingester (ref-derived classification), and the forwarder (UserActivityEvent).
//
// Precedence shipped > in_progress > orphaned governs two rules:
//   - the denormalised link state is upgrade-only — a feature-ref re-link never
//     downgrades a shipped link (RepoStore.UpsertCheckpointCommit's CASE).
//   - a checkpoint inherits the highest-precedence state among its linking
//     commits (D3 — StateByCheckpoint / MaxState below).
//
// Orphaned is written by the rollup recompute's checkpoint-axis reconcile
// (RepoStore.ReconcileCheckpointCommitStates, from the default-branch reachable
// set). It never reaches my_activity: the /me forwards clamp to a counted state
// (ingest.myActivityState), keeping /me branch-agnostic.
type CommitState string

const (
	// StateShipped — reachable from the repo's default branch (landed).
	StateShipped CommitState = "shipped"
	// StateInProgress — on a branch, not yet on the default branch.
	StateInProgress CommitState = "in_progress"
	// StateOrphaned — reachable from no branch; excluded from counts.
	StateOrphaned CommitState = "orphaned"
)

// ResolveBranchName picks the bare branch name the ?branch= list filter resolves
// its reachable-SHA set for (read through from entiredb): the requested branch when
// given, else the repo's default branch, else "main" (entire.io's fallback).
// Both inputs are normalized
// (refs/heads/ stripped) so a stored "refs/heads/main" default and a bare "main"
// request resolve identically. Membership is keyed by bare branch name.
func ResolveBranchName(requested, defaultBranch string) string {
	if b := normalizeBranch(requested); b != "" {
		return b
	}
	if d := normalizeBranch(defaultBranch); d != "" {
		return d
	}
	return "main"
}

func normalizeBranch(b string) string {
	return strings.TrimPrefix(b, "refs/heads/")
}

// statePrecedence ranks states shipped(3) > in_progress(2) > orphaned(1).
// Unknown/empty sorts lowest so it never wins a comparison.
func statePrecedence(s CommitState) int {
	switch s {
	case StateShipped:
		return 3
	case StateInProgress:
		return 2
	case StateOrphaned:
		return 1
	default:
		return 0
	}
}

// MaxState returns the higher-precedence of two states (shipped > in_progress >
// orphaned). It is the Go home of the precedence order — matching the
// UpsertCheckpointCommit upgrade-only CASE — so a checkpoint's D3 state can be
// resolved in Go (StateByCheckpoint) without re-deriving the ranking.
func MaxState(a, b CommitState) CommitState {
	if statePrecedence(b) > statePrecedence(a) {
		return b
	}
	return a
}

// CheckpointKey identifies a checkpoint within a repo. Personal-activity reads
// dedup by this key — not by checkpoint id alone — to match the team aggregate's
// (repo_id, checkpoint_id) grouping; a checkpoint id is unique only within a repo.
type CheckpointKey struct {
	RepoID       string
	CheckpointID string
}

// StateByCheckpoint resolves each checkpoint's lifecycle state from the personal
// activity rows referencing it: the highest-precedence state (D3) across its
// linking-commit rows, so a multi-commit checkpoint counts once,
// shipped-if-any-link-shipped. Only checkpoint rows participate. (my_activity rows
// are always counted states — shipped/in_progress — so this dedups a checkpoint's
// links to one counted row.)
func StateByCheckpoint(rows []MyActivityRow) map[CheckpointKey]CommitState {
	out := map[CheckpointKey]CommitState{}
	for _, r := range rows {
		if r.Type != "checkpoint" {
			continue
		}
		k := CheckpointKey{RepoID: r.RepoID, CheckpointID: r.CheckpointID}
		out[k] = MaxState(out[k], r.State)
	}
	return out
}

